impl CapabilityClient for ProjectsClient {
    type Dependencies = PluginDependencies;
    type Error = RuntimeFailure;

    const CAPABILITY_ID: &'static str = CAPABILITY_ID;
    const DESCRIPTOR_VERSION: &'static str = DESCRIPTOR_VERSION;

    fn from_dependencies(dependencies: &PluginDependencies) -> Result<Self, RuntimeFailure> {
        Ok(Self {
            archive_issue: dependencies.one::<ProjectsArchiveIssue>()?,
            archive_project: dependencies.one::<ProjectsArchiveProject>()?,
            create_issue: dependencies.one::<ProjectsCreateIssue>()?,
            create_project: dependencies.one::<ProjectsCreateProject>()?,
            get_issue: dependencies.one::<ProjectsGetIssue>()?,
            get_project: dependencies.one::<ProjectsGetProject>()?,
            list_activity: dependencies.one::<ProjectsListActivity>()?,
            list_issues: dependencies.one::<ProjectsListIssues>()?,
            list_projects: dependencies.one::<ProjectsListProjects>()?,
            move_issue: dependencies.one::<ProjectsMoveIssue>()?,
            put_external_link: dependencies.one::<ProjectsPutExternalLink>()?,
            update_issue: dependencies.one::<ProjectsUpdateIssue>()?,
            update_project: dependencies.one::<ProjectsUpdateProject>()?,
        })
    }

    fn already_connected() -> RuntimeFailure {
        RuntimeFailure::PluginFailure {
            detail: format!("Capability Port {CAPABILITY_ID} was connected more than once"),
        }
    }
}

impl CapabilityClientMany for ProjectsClient {
    fn many_from_dependencies(
        dependencies: &PluginDependencies,
    ) -> Result<Vec<BoundCapabilityClient<Self>>, RuntimeFailure> {
        dependencies
            .bindings()
            .iter()
            .filter(|binding| binding.capability_id() == CAPABILITY_ID)
            .map(|binding| {
                Ok(BoundCapabilityClient::new(
                    binding.provider_instance(),
                    Self {
                    archive_issue: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<ProjectsArchiveIssue>()?,
                    archive_project: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<ProjectsArchiveProject>()?,
                    create_issue: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<ProjectsCreateIssue>()?,
                    create_project: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<ProjectsCreateProject>()?,
                    get_issue: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<ProjectsGetIssue>()?,
                    get_project: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<ProjectsGetProject>()?,
                    list_activity: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<ProjectsListActivity>()?,
                    list_issues: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<ProjectsListIssues>()?,
                    list_projects: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<ProjectsListProjects>()?,
                    move_issue: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<ProjectsMoveIssue>()?,
                    put_external_link: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<ProjectsPutExternalLink>()?,
                    update_issue: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<ProjectsUpdateIssue>()?,
                    update_project: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<ProjectsUpdateProject>()?,
                    },
                ))
            })
            .collect()
    }
}

